+/** A full version: MAJOR.MINOR.PATCH. */
+type Version = readonly [bigint, bigint, bigint];
+
+/** A possibly partial version. `null` is a wildcard or an omitted number. */
+type Partial = readonly [bigint | null, bigint | null, bigint | null];
+
+type Predicate = (v: Version) => boolean;
+
+const FULL_VERSION = /^(\d+)\.(\d+)\.(\d+)$/;
+const COMPARATOR = /^(<=|>=|<|>|=|~|\^)?(.*)$/;
+
+function compareVersions(a: Version, b: Version): number {
+  for (let i = 0; i < 3; i++) {
+    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
+  }
+  return 0;
+}
+
+function parseVersion(text: string): Version {
+  const m = FULL_VERSION.exec(text);
+  if (!m) throw new Error(`Invalid version: "${text}"`);
+  return [BigInt(m[1]), BigInt(m[2]), BigInt(m[3])];
+}
+
+function parsePartial(text: string): Partial {
+  const parts = text.split(".");
+  if (parts.length > 3) throw new Error(`Invalid version: "${text}"`);
+  const nums: (bigint | null)[] = [null, null, null];
+  let wildcard = false;
+  for (let i = 0; i < parts.length; i++) {
+    const part = parts[i];
+    if (part === "x" || part === "X" || part === "*") {
+      wildcard = true;
+    } else if (/^\d+$/.test(part) && !wildcard) {
+      nums[i] = BigInt(part);
+    } else {
+      throw new Error(`Invalid version: "${text}"`);
+    }
+  }
+  return nums as unknown as Partial;
+}
+
+/** The lowest version a partial version names, with omitted numbers as zero. */
+funct
